// Literal port of the team's Casa3DSDK (module furniture/extra-types). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installFurnitureExtraTypes(K: Kernel, _shared: Shared): void {
  const seedKey = (id: any): any => K.seedKey(id);
  const { CARS, CAR_BY_STYLE, FURNITURE, SEED, STYLE, carModel, ceilingLamp, cursor, floorLamp, kit2, lightStyle, lightSwitch, outdoorLamp, palm_tree, planterModel, potPlant, rngString, sconce, shrubModel, tableLamp, tablePot, treeModel, tuft } = K;
  // ---------- extra types linked to the table ----------
  function extraTypes(T, props) {
    const origCar = T.garage_car;
    const car = (M, A) => {
      const structure = STYLE(), list = CAR_BY_STYLE[structure] || CAR_BY_STYLE.mid, r = rngString(SEED() + '|' + (seedKey(M.seed) || M.id || '') + '|' + Math.round((M.x || 0) * 10) + '|' + Math.round((M.z || 0) * 10) + '|carro');
      const k = list[Math.floor(r() * list.length)], paint = 1 + Math.floor(r() * 8); // seed = paint colour (8 colours per model, so the cache does not grow)
      if (!carModel(k, paint)) { if (origCar) origCar.f(M, A); return; }
      const K = kit2(M, A, 0), [px, py, pz] = K.W(0, 0, 0);
      CARS.push({ x: px, y: py, z: pz, ry: M.ry, w: M.w || 1.8, d: M.d || 4.2, k, seed: paint, parent: cursor.group });
    };
    const mine = (type, f, source = 'game') => { T[type] = { f, source }; };
    for (const t of ['ceiling_light', 'pendant', 'track_spot', 'chandelier']) mine(t, (M, A) => ceilingLamp(M, A, t === 'ceiling_light' ? lightStyle(M) : t === 'pendant' ? 'pendant' : t === 'chandelier' ? 'chandelier' : 'track'), 'game (lamps)');
    mine('table_lamp', (M, A) => tableLamp(M, A, M.y || 0)); mine('car', car); mine('car_small', car); mine('garage_car', car); mine('outdoor_lamp', outdoorLamp); mine('floor_lamp', floorLamp); mine('floor_lamp', floorLamp); mine('sconce', sconce); mine('light_switch', lightSwitch);
    mine('mirror', FURNITURE.mirror); mine('curtain', FURNITURE.curtain); mine('shower', FURNITURE.box); mine('shower_large', FURNITURE.box); mine('laundry_tub', FURNITURE.laundry_tub); mine('clothesline', FURNITURE.clothesline); mine('water_tank', FURNITURE.water_tank); mine('mailbox', FURNITURE.mailbox); mine('correio', FURNITURE.mailbox);
    mine('palm_tree', (M, A) => palm_tree(M, A, { coconut: true })); mine('fruit_tree', (M, A) => treeModel(M, A, { fruit: [0xd8332a, 0xf2a22a, 0xf0d030] }));
    mine('tree_small', (M, A) => treeModel(M, A, {})); mine('tree_large', (M, A) => treeModel(M, A, { lowCrown: true })); mine('shrub', (M, A) => shrubModel(M, A, {})); mine('flowering_shrub', (M, A) => shrubModel(M, A, { flower: 0.9 }));
    mine('plant_tall', (M, A) => potPlant(M, A, {})); mine('plant_short', (M, A) => potPlant(M, A, {})); mine('outdoor_pot', (M, A) => potPlant(M, A, {})); mine('floor_plant', (M, A) => potPlant(M, A, {})); mine('table_plant', tablePot);
    mine('planter_bed', (M, A) => planterModel(M, A, {})); mine('planter_bed_small', (M, A) => planterModel(M, A, {})); mine('garden_bed', (M, A) => planterModel(M, A, { type: 'grass' }));
    mine('tuft', (M, A) => { const K = kit2(M, A), rnd = rngString(SEED() + '|' + seedKey(M.seed) + '|tf'); tuft(K, 0, 0, 0, Math.max(0.2, (M.w || 0.4) / 2), 16, 0x4f8a42, rnd); });
  }
  Object.assign(K, { extraTypes });
}
